const values = [30, 55, 80, 45, 120, 90, 60, 100];
const peak = Math.max(...values);
const out = [
  { payload: { wake: true } },
  { payload: { clear: 'white' } },
  { payload: { rect: { x: 4, y: 4, w: 392, h: 292, color: 'black', fill: false } } },
  { payload: { rect: { x: 5, y: 5, w: 390, h: 40, color: 'red', fill: true } } },
  { payload: { line: { x0: 30, y0: 270, x1: 370, y1: 270, color: 'black' } } },
  { payload: { line: { x0: 30, y0: 70, x1: 30, y1: 270, color: 'black' } } },
];
values.forEach((v, i) => out.push({ payload: { rect: { x: 45 + i * 40, y: 270 - v, w: 28, h: v, color: v === peak ? 'red' : 'black', fill: true } } }));
out.push({ payload: { show: true } });
return [out];
